  function invalidateQbPreview() {
    invalidate();
    setError('');
    setFiles((previous) => {
      const source = previous.QBO;
      if (!source) return previous;
      return {
        ...previous,
        QBO: {
          ...source,
          bindings: undefined,
          excludedTargets: [],
          result: {
            ok: false,
            rows: [],
            manifest: null,
            mapping: null,
            duplicate: false,
            controls: { signedCents: 0, debitCents: null, creditCents: null, excludedRows: [] },
            issues: [
              {
                code: 'REPORT_SETTINGS_CHANGED',
                severity: 'error',
