        ? {
            profile: 'qbo-transaction-journal-v1',
            qboTransactionJournalCompanyName: reportCompanyName.trim(),
            coverageConfirmed: false,
          }
        : {}),
      fileName: source.file.name,
      originalBytes: source.bytes,
