          'Enter the independently reviewed company name printed on the QBO Transaction Journal.',
        );
      const next: Partial<Record<MainKind, FileState>> = {};
      let seen: string[] = [];
      for (const kind of ['ST', 'QBO', 'BANK'] as MainKind[]) {
